if(s.page==='payment')html=orderHeader('Finalizar pedido','cart')+`<main class="order-body"><span class="lk-kicker">ÚLTIMO PASSO</span><h2>Como prefere pagar?</h2><p>Escolha uma forma para testar a experiência.</p><div class="lk-payment-total"><span>TOTAL DO SEU PEDIDO</span><strong>${money(orderTotal())}</strong><small>${orderCount()} ${orderCount()===1?'item':'itens'} · ${s.service==='local'?'Comer aqui':'Para levar'}</small></div><div class="pay-options">${[['card','Cartão','Crédito ou débito','card'],['pix','Pix','Pagamento instantâneo','pix']].map(([v,n,d,i])=>actionButton('method',tlOrderIcon(i)+`<span><strong>${n}</strong><small>${d}</small></span><i class="lk-radio"></i>`,s.method===v?'chosen':'',`data-value="${v}" aria-pressed="${s.method===v}" ${s.processing?'disabled':''}`)).join('')}</div><div class="simulation-note"><strong>Você está em uma demonstração.</strong><span>Não informe dados bancários. Nenhuma cobrança será realizada.</span></div></main>`+orderFooter(actionButton('pay',s.processing?'<span class="lk-spinner"></span> Confirmando na simulação…':'Simular pagamento <span>→</span>','strong',s.processing?'disabled aria-busy="true"':''))+demoMark();
if(s.page==='success'){const o=s.completed;html=orderHeader('Pedido confirmado')+`<main class="order-body lk-success"><div class="success-mark">${tlOrderIcon('check')}</div><span class="lk-kicker">TUDO CERTO POR AQUI</span><h2>Pedido feito.<br>Agora é com a cozinha.</h2><p>Pagamento aprovado na demonstração.</p><div class="order-number"><span>SEU NÚMERO</span><strong>${o.number}</strong><small>${o.service==='local'?'Para comer aqui':'Para levar'}</small></div><div class="lk-success-summary">${o.items.map(line=>`<div class="summary-item"><span>${line.quantity}× ${line.name}</span><strong>${money(line.unit*line.quantity)}</strong></div>`).join('')}<div class="totals-row"><span>Total</span><strong>${money(o.total)}</strong></div></div><p class="lk-print-hint">Seu comprovante também sai<br>pela impressora do totem.</p></main>`+orderFooter(actionButton('print','Ver impressão','soft')+actionButton('new','Novo pedido →','strong'))+demoMark()}
orderPlane.innerHTML='<div class="order-layout">'+html+'</div><div id="lk-notice" role="status" aria-live="polite"></div>';if(s.processing)orderPlane.querySelectorAll('button').forEach(b=>b.disabled=true);const body=orderPlane.querySelector('.order-body');if(body)body.scrollTop=scroll;if(focused?.action){const target=[...orderPlane.querySelectorAll('button')].find(b=>b.dataset.action===focused.action&&b.dataset.value===focused.value&&b.dataset.index===focused.index);target?.focus({preventScroll:true})}tlLastOrderPage=s.page;tlLastProduct=s.selected;tlId('tl-cart-summary').textContent=s.completed&&s.page==='success'?'Pedido #'+s.completed.number:orderCount()?orderCount()+(orderCount()===1?' item · ':' itens · ')+money(orderTotal()):'Nenhum item ainda';rasterOrderDisplay();positionOrderScreen();
